### My answer to the user’s prompt

A reliable way to keep **“See more” visible at the end of the collapsed line** is to measure the text with an off-screen `Text`, then render the truncated text and link in a one-line row. This avoids appending the link after the entire string, where it could itself be clipped.

```jsx
import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

export default function ExpandableText({
  text,
  textStyle,
  linkStyle,
  containerStyle,
}) {
  const [width, setWidth] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setHasMore(false);
    setExpanded(false);
  }, [text]);

  const handleTextLayout = ({ nativeEvent }) => {
    setHasMore(nativeEvent.lines.length > 1);
  };

  return (
    <View
      style={containerStyle}
      onLayout={({ nativeEvent }) => setWidth(nativeEvent.layout.width)}
    >
      {width > 0 && (
        <Text
          accessible={false}
          onTextLayout={handleTextLayout}
          style={[textStyle, styles.measure, { width }]}
        >
          {text}
        </Text>
      )}

      {expanded ? (
        <Text style={textStyle}>
          {text}
          {' '}
          <Text
            accessibilityRole="button"
            onPress={() => setExpanded(false)}
            style={linkStyle || styles.link}
          >
            See less
          </Text>
        </Text>
      ) : (
        <View style={styles.row}>
          <Text numberOfLines={1} ellipsizeMode="tail" style={[textStyle, styles.truncated]}>
            {text}
          </Text>
          {hasMore && (
            <Text
              accessibilityRole="button"
              onPress={() => setExpanded(true)}
              style={linkStyle || styles.link}
            >
              {' '}See more
            </Text>
          )}
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  measure: {
    position: 'absolute',
    left: -10000,
    opacity: 0,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  truncated: {
    flexShrink: 1,
  },
  link: {
    color: '#007AFF',
  },
});
```

