            accessibilityRole="button"
            accessibilityLabel={moreLabel}
            hitSlop={8}
          >
            <Text style={[styles.actionText, textStyle]}>{moreLabel}</Text>
          </Pressable>
        </View>
      ) : (
        <Text style={textStyle} numberOfLines={1} ellipsizeMode="tail">
          {text}
        </Text>
      )}
    </View>
  );
