  container: {
    position: 'relative',
  },
  measureText: {
    position: 'absolute',
    left: 0,
    right: 0,
    top: 0,
    opacity: 0,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'baseline',
  },
  collapsedText: {
